import{e as a,ab as r,a1 as t,m as n,r as i,p as l}from"./chunks/framework.BGh0NSIy.js";const m=JSON.parse('{"title":"Keep Android Open 🔓","description":"Android will become a locked-down platform in less than 200 days.","frontmatter":{"title":"Keep Android Open 🔓","description":"Android will become a locked-down platform in less than 200 days.","date":"2026-02-26T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/KeepAndroidOpen.md","filePath":"posts/KeepAndroidOpen.md"}'),s={name:"posts/KeepAndroidOpen.md"};function d(p,e,h,c,u,g){const o=r("Post");return t(),n("div",null,[i(o,{authors:""}),e[0]||(e[0]=l('<h3 id="android-will-become-a-locked-down-platform-in-less-than-200-days" tabindex="-1">Android will become a locked-down platform in less than 200 days. <a class="header-anchor" href="#android-will-become-a-locked-down-platform-in-less-than-200-days" aria-label="Permalink to &quot;Android will become a locked-down platform in less than 200 days.&quot;">​</a></h3><p>In August 2025, Google announced that as of September 2026, it will no longer be possible to develop apps for the Android platform <strong>without first registering centrally with Google</strong>. This registration will involve:</p><ul><li>Paying a fee to Google</li><li>Agreeing to Google’s Terms and Conditions</li><li>Providing government identification</li><li>Uploading evidence of the developer’s private signing key</li><li>Listing all current and future application identifiers</li></ul><hr><h3 id="what-this-means-for-you" tabindex="-1">What this means for you <a class="header-anchor" href="#what-this-means-for-you" aria-label="Permalink to &quot;What this means for you&quot;">​</a></h3><ul><li><p>You will no longer be able to choose what software you run on your phone. You will be forced only to use apps that Google has deemed okay for you to install.</p></li><li><p>Creators / developers will no longer be able to make or share apps without first seeking the permission of Google, which will vastly limit the amount of good apps that exist, similar to Apple&#39;s ecosystem.</p></li></ul><hr><h3 id="how-you-can-help" tabindex="-1">How you can help <a class="header-anchor" href="#how-you-can-help" aria-label="Permalink to &quot;How you can help&quot;">​</a></h3><p><strong>Developers: Resist and refuse</strong></p><p>If you are an app developer, <em>do not sign up</em> for the early access program, perform identity verification, or accept an invitation to the Android Developer Console. Respond (politely) to any invitation with a list of your concerns and objections.</p><p>It is only through developer acquiescence and capitulation that their takeover plan can possibly succeed.</p><p>Discourage fellow app developers and organizations from signing up to the program. Use community forums, social media, and blog posts to spread the message. Include the <a href="https://github.com/woheller69/FreeDroidWarn" target="_blank" rel="noreferrer">FreeDroidWarn library</a> in your code to inform your app users. If you manage a web site, consider adding the <a href="https://keepandroidopen.org/banner" target="_blank" rel="noreferrer">countdown banner</a> to the top of your page.</p><p>If you are a Google employee or contractor of good conscience and have additional insight about the program, including planned technical implementation details or additional rationales for the program, please reach out to <code>tips@keepandroidopen.org</code> from a non-work machine and a non-gmail account. Your information will be kept in strict confidence.</p><hr><h3 id="everyone-make-your-voice-heard" tabindex="-1">Everyone: Make your voice heard <a class="header-anchor" href="#everyone-make-your-voice-heard" aria-label="Permalink to &quot;Everyone: Make your voice heard&quot;">​</a></h3><ul><li><a href="https://f-droid.org/" target="_blank" rel="noreferrer">Install F-Droid</a> on your Android device(s) (or similar <a href="https://fmhy.pages.dev/mobile#foss-apks" target="_blank" rel="noreferrer">FOSS installers</a>). The more people that use alternative app marketplaces, the harder it will be to shut them out.</li><li>Provide feedback directly to Google using their <a href="https://docs.google.com/forms/d/e/1FAIpQLSfN3UQeNspQsZCO2ITkdzMxv81rJDEGGjO-UIDDY28Rz_GEVA/viewform?pli=1" target="_blank" rel="noreferrer">Android developer verification requirements survey</a>.</li><li>Make your voice heard on social media and with blog posts, and link to <a href="https://keepandroidopen.org" target="_blank" rel="noreferrer">https://keepandroidopen.org</a></li><li>Combat astroturfing: when you encounter suspect posts on community forums and social media in support of the policy (“Well, actually…”), challenge them and do not be shy. -Help this project out by <a href="https://github.com/keepandroidopen/keepandroidopen.github.io/blob/main/src/content/pages/en/index.md" target="_blank" rel="noreferrer">editing this page</a> with more useful information.</li><li><a href="https://www.change.org/p/stop-google-from-limiting-apk-file-usage/" target="_blank" rel="noreferrer">Sign this change.org petition</a></li></ul><hr><h3 id="consumers-contact-national-regulators" tabindex="-1">Consumers: Contact national regulators <a class="header-anchor" href="#consumers-contact-national-regulators" aria-label="Permalink to &quot;Consumers: Contact national regulators&quot;">​</a></h3><p><strong><a href="https://keepandroidopen.org/" target="_blank" rel="noreferrer">List of Regulators</a></strong> (at bottom)</p><p>Regulators worldwide are genuinely concerned about monopolies and the centralization of power in the tech sector, and want to hear directly from individuals who are affected and concerned. When contacting regulators directly, you should be polite and specific about the harm you believe these policies will cause, both to consumers and to competition.</p><p>Complaints are especially impactful when they are authored by a citizen of that country or region, and when the language of the email is written in one of the official languages of the region&#39;s governing body. Request a written acknowledgement of the complaint, and consider forwarding any responses you receive to <code>victory@keepandroidopen.org</code> so that we might highlight and reference them.</p><hr><p><strong>This information above is from the following page</strong>:</p><p><a href="https://keepandroidopen.org/" target="_blank" rel="noreferrer">https://keepandroidopen.org/</a></p><p><strong>Discussion Post</strong>:</p><p><a href="https://redd.it/1rf71xj" target="_blank" rel="noreferrer">https://redd.it/1rf71xj</a></p>',26))])}const y=a(s,[["render",d]]);export{m as __pageData,y as default};
